INSERT OR IGNORE INTO materials(id,title,description,category,body,task,status) VALUES('dont-stop','Don’t Stop!','Сөзді ұмытсаң да, сөйлеуді жалғастыр.','Word block','Umbrella сөзін айтпай түсіндір: It is something we use when it rains.
Dentist: It is a doctor who helps people with their teeth.

Авторлық оқу тапсырмасы, жобадағы мысалдар негізінде.','Explain a bicycle without using the word bicycle.','published');
INSERT OR IGNORE INTO materials(id,title,description,category,body,task,status) VALUES('charity','Organise a School Charity Event','AI-мен дайындал, сыныптастарыңмен шешім қабылда.','Real-life dialogue','Сөздер: donate, collect, volunteer.
AI идея мен сөз ұсынады. Мұғалім топтық талқылауды және ауызша таныстыруды бағалайды.

Авторлық оқу тапсырмасы, жобадағы мысалдар негізінде.','Suggest one charity event for your school. Explain who can help and why it matters.','published');
